def kartela_kur(apps, schema_editor):
    """Rono 7 renk, Bienca 4 desen; seriler kartelaya bağlanır; 'Rona' malzeme adı 'Rono' olur."""
    Renk = apps.get_model("uretim", "Renk")
    KatalogSerisi = apps.get_model("uretim", "KatalogSerisi")
    DeriTuru = apps.get_model("uretim", "DeriTuru")
    for sira, (kod, ad, grup) in enumerate(RENKLER, 1):
        Renk.objects.get_or_create(kod=kod, defaults={"ad": ad, "grup": grup, "sira": sira})
    KatalogSerisi.objects.filter(ad__iexact="Rono").update(kartela="rono")
    KatalogSerisi.objects.filter(ad__iexact="Bienca").update(kartela="bienca")
    for tur in DeriTuru.objects.filter(ad__icontains="Rona"):
        yeni = tur.ad.replace("Rona", "Rono")
        if not DeriTuru.objects.filter(ad=yeni).exists():
            tur.ad = yeni
            tur.save(update_fields=["ad"])


